fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since the two vectors have the same length, we can safely
    // iterate over pairs of elements and compare them.
    a.iter()
        .zip(b.iter())
        .map(|(&val_a, &val_b)| val_a >= val_b)
        .collect()
}